from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
targets=[repo/'adapters/workday.py',repo/'tests/test_workday_adapter.py']
for p in targets:
 if subprocess.run(['git','status','--porcelain','--',p.relative_to(repo).as_posix()],cwd=repo,capture_output=True,text=True,check=True).stdout.strip(): raise SystemExit('TARGET_DIRTY '+str(p))
if subprocess.run(['git','rev-parse','HEAD'],cwd=repo,capture_output=True,text=True,check=True).stdout.strip()!='fcec90b66dc3acc1609ff6a0fe00f851e6c7219d': raise SystemExit('HEAD_CHANGED')
src=targets[0].read_text()
anchor='''            if len(enabled) > 1:
                return False
            return await _click_named(form, ("Create Account", "Register"))'''
if src.count(anchor)!=1: raise SystemExit('ANCHOR_CHANGED')
test='''

@pytest.mark.asyncio
async def test_registration_never_clicks_when_create_controls_disabled():
    playwright_module = pytest.importorskip("playwright.async_api")
    async with playwright_module.async_playwright() as playwright:
        try:
            browser = await playwright.chromium.launch(headless=True)
        except Exception as exc:
            pytest.skip(f"Chromium unavailable: {type(exc).__name__}")
        try:
            page = await browser.new_page()
            await page.set_content(
                '<form><input data-automation-id="verifyPassword" type="password">'
                '<button data-automation-id="createAccountSubmitButton" disabled>Create Account</button>'
                '</form>'
            )
            assert not await _click_create_account_submit(page)
        finally:
            await browser.close()
'''
with targets[1].open('a') as f:f.write(test)
def run(testargs,timeout):
 cmd=[str(repo/'.venv/bin/python'),'-m','pytest','-q','--maxfail=1']+testargs
 p=subprocess.Popen(cmd,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try: out,err=p.communicate(timeout=timeout)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try: out,err=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:
   os.killpg(p.pid,signal.SIGKILL);out,err=p.communicate()
  print('TIMEOUT',testargs,out[-1600:]);raise SystemExit(124)
 print('TEST',testargs,'EXIT',p.returncode,out[-2600:],err[-300:])
 return p.returncode,out
code,out=run(['tests/test_workday_adapter.py','-k','registration_never_clicks_when_create_controls_disabled'],70)
if code==0:
 print('ALREADY_SAFE: no source edit needed; retain only regression test')
else:
 if '1 failed' not in out: raise SystemExit('INFRA_FAILURE')
 # Avoid name-based fallback when explicit registration automation controls are present but disabled.
 patch='''            if len(enabled) > 1:
                return False
            if await candidates.count():
