 targets[0].write_text(src.replace(anchor,patch,1))
 code,_=run(['tests/test_workday_adapter.py','-k','registration_never_clicks_when_create_controls_disabled'],70)
 if code: raise SystemExit('GREEN_FAILED')
for args,timeout in [(['tests/test_workday_adapter.py'],180),(['tests/test_ats_adapter_contract.py'],200),([],520)]:
